public class Main {
    static int countPresent(String[] items) {
        int count = 0;
        for (String item : items) if (item != null) count++;
        return count;
    }
    public static void main(String[] args) {
        System.out.println(countPresent(new String[]{null, "", "a"}));
    }
}
